"""Satellite availability tables: when the remote archive has data for each satellite of a recipe.

A recipe's ``satellite`` parameter lists every satellite the recipe *can* process, but not *when*
each one has data. A recipe module may declare that in an optional module-level attribute, next to
``CLI_DEFAULTS`` and ``PLOT_DEFAULTS``::

    # generated by scripts/generate_satellite_availability.py
    SATELLITE_AVAILABILITY = Path(__file__).with_name("mpa_availability.toml")

    # or written by hand, e.g. coarse mission lifetimes
    SATELLITE_AVAILABILITY = {
        "a": [(date(2012, 9, 1), date(2019, 10, 18))],
        "b": [(date(2012, 9, 1), date(2019, 7, 19))],
    }

A table maps each ``satellite`` value to sorted, non-overlapping, closed day intervals in which the
archive has data for the recipe's product. Short gaps are merged into the surrounding interval, so a
table is a hint about coverage, not a guarantee that every file exists. A TOML file holds the
intervals in its ``[satellites]`` table as ``[first, last]`` pairs of TOML dates; any other key is
descriptive metadata::

    # SPDX-FileCopyrightText: 2026 GFZ Helmholtz Centre for Geosciences
    #
    # SPDX-License-Identifier: Apache-2.0

    max_gap_days = 5

    [satellites]
    "010" = [
      [2008-01-03, 2008-02-06],
      [2013-06-23, 2014-05-01],
    ]

The command line uses :func:`satellite_availability` to restrict ``--satellite all`` to satellites
with data, to warn about explicitly requested satellites without data, and for ``--list-satellites``.
"""

from __future__ import annotations

import importlib
import itertools
import sys
import types
import typing
from collections.abc import Mapping, Sequence
from datetime import date, datetime, timezone
from pathlib import Path
from typing import Any, Literal, get_args, get_origin

AVAILABILITY_ATTRIBUTE = "SATELLITE_AVAILABILITY"
"""Name of the optional module-level attribute in which a recipe module declares its table."""

AVAILABILITY_PARAMETER = "satellite"
"""The recipe parameter whose values key an availability table."""

DateInterval = tuple[date, date]
"""A closed interval of days, ``(first, last)``."""

AvailabilityTable = dict[str, list[DateInterval]]
"""Day intervals with data, per ``satellite`` value."""

AvailabilitySource = Mapping[str, Sequence[DateInterval]] | Path
"""What a recipe module may declare: a table, or the path of a TOML file holding one."""


def _module_of(recipe: Any) -> types.ModuleType:  # noqa: ANN401
    """Return the module a recipe function, module or registry entry refers to."""
    if isinstance(recipe, types.ModuleType):
        return recipe
    module_name = getattr(recipe, "module", None)  # an `el_paso.cli.app.RecipeEntry`
    if isinstance(module_name, str):
        return importlib.import_module(module_name)
    module_name = getattr(recipe, "__module__", None)
    if callable(recipe) and isinstance(module_name, str):
        return sys.modules.get(module_name) or importlib.import_module(module_name)
    msg = f"Expected a recipe function, a recipe module or a registry entry, got {recipe!r}."
    raise TypeError(msg)


def get_availability_source(recipe: Any) -> AvailabilitySource | None:  # noqa: ANN401
    """Return what a recipe module declares as ``SATELLITE_AVAILABILITY``, without loading it.

    Args:
        recipe (Any): A recipe function, its module, or an ``el_paso.cli.app.RecipeEntry``.

    Returns:
        AvailabilitySource | None: The declared table or TOML path, or ``None`` if the module
        declares none.
    """
    return getattr(_module_of(recipe), AVAILABILITY_ATTRIBUTE, None)


def _parse_day(value: Any, where: str) -> date:  # noqa: ANN401
    if isinstance(value, datetime):
        msg = f"{where}: expected a date, got the datetime {value!r}."
        raise TypeError(msg)
    if isinstance(value, date):
        return value
    if isinstance(value, str):
        try:
            return date.fromisoformat(value)
        except ValueError:
            pass
    msg = f"{where}: expected a date or a YYYY-MM-DD string, got {value!r}."
    raise ValueError(msg)


def load_availability_table(source: AvailabilitySource) -> AvailabilityTable:
    """Read an availability table into its in-memory form.

    Only the shape is checked here; see :func:`check_availability_table` for the full validation.

    Args:
        source (AvailabilitySource): A table, or the path of a TOML file holding one in its
            ``[satellites]`` table.

    Returns:
        AvailabilityTable: The intervals per satellite, as ``(first, last)`` date tuples.

    Raises:
        TypeError: If the source does not have the shape of a table, or an interval bound is a
            datetime rather than a date.
        ValueError: If an interval bound is not a valid date.
    """
    name = str(source) if isinstance(source, Path) else "availability table"
    if isinstance(source, Path):
        import tomllib  # noqa: PLC0415

        content = tomllib.loads(source.read_text(encoding="utf-8"))
        if not isinstance(content.get("satellites"), dict):
            msg = f"{name}: expected a [satellites] table."
            raise TypeError(msg)
        raw: Mapping[str, Any] = content["satellites"]
    else:
        raw = source

    table: AvailabilityTable = {}
    for satellite, intervals in raw.items():
        where = f"{name}, satellite {satellite!r}"
        if isinstance(intervals, (str, bytes)) or not isinstance(intervals, Sequence):
            msg = f"{where}: expected a list of (first, last) intervals, got {intervals!r}."
            raise TypeError(msg)
        parsed: list[DateInterval] = []
        for interval in intervals:
            if isinstance(interval, (str, bytes)) or not isinstance(interval, Sequence) or len(interval) != 2:
                msg = f"{where}: expected a (first, last) pair, got {interval!r}."
                raise TypeError(msg)
            parsed.append((_parse_day(interval[0], where), _parse_day(interval[1], where)))
        table[str(satellite)] = parsed
    return table


def _to_day(time: datetime | date) -> date:
    """Return the UTC day of a time; naive datetimes are taken as UTC."""
    if isinstance(time, datetime):
        if time.tzinfo is not None:
            time = time.astimezone(timezone.utc)
        return time.date()
    return time


def overlapping_intervals(
    table: AvailabilityTable, start_time: datetime | date, end_time: datetime | date
) -> dict[str, list[DateInterval]]:
    """Return, per satellite with data in a time range, its intervals that overlap the range.

    Args:
        table (AvailabilityTable): A loaded table, see :func:`load_availability_table`.
        start_time (datetime | date): Start of the range.
        end_time (datetime | date): End of the range, inclusive.

    Returns:
        dict[str, list[DateInterval]]: The satellites with at least one overlapping interval, in
        table order, with those intervals unclipped.
    """
    first, last = _to_day(start_time), _to_day(end_time)
    overlaps = {
        satellite: [(start, end) for start, end in intervals if start <= last and end >= first]
        for satellite, intervals in table.items()
    }
    return {satellite: intervals for satellite, intervals in overlaps.items() if intervals}


def satellite_availability(
    recipe: Any,  # noqa: ANN401
    start_time: datetime | date,
    end_time: datetime | date,
) -> dict[str, list[DateInterval]] | None:
    """Return the satellites of a recipe that have data in a time range, and their coverage.

    A satellite counts as available if any of its intervals overlaps the range, including a
    partial overlap at either end. The range is compared by UTC day, both ends inclusive.

    Example:
        ```python
        import el_paso as ep
        from datetime import datetime, timezone

        coverage = ep.satellite_availability(
            ep.recipes.lanl_geogrid.process_lanl_geogrid_mpa_electrons,
            datetime(2017, 4, 1, tzinfo=timezone.utc),
            datetime(2017, 4, 30, tzinfo=timezone.utc),
        )
        sorted(coverage)  # ['010', '070', '130', '190', '310']
        ```

    Args:
        recipe (Any): A recipe function, its module, an ``el_paso.cli.app.RecipeEntry``, or an
            availability table or TOML path itself.
        start_time (datetime | date): Start of the range.
        end_time (datetime | date): End of the range, inclusive.

    Returns:
        dict[str, list[DateInterval]] | None: The satellites with data in the range, each with its
        intervals that overlap the range (not clipped to it), or ``None`` if the recipe declares no
        table, in which case availability is unknown. An empty dict means that no satellite has
        data in the range.
    """
    source = recipe if isinstance(recipe, (Mapping, Path)) else get_availability_source(recipe)
    if source is None:
        return None
    return overlapping_intervals(load_availability_table(source), start_time, end_time)


def _satellite_choices(recipe: Any) -> tuple[str, ...]:  # noqa: ANN401
    """Return the values of a recipe's ``satellite`` Literal, which are the keys its table may use.

    Args:
        recipe (Any): The recipe function.

    Returns:
        tuple[str, ...]: The allowed ``satellite`` values, in declaration order.

    Raises:
        TypeError: If the recipe has no ``satellite`` parameter annotated with a Literal.
    """
    hint = typing.get_type_hints(recipe).get(AVAILABILITY_PARAMETER)
    if get_origin(hint) in (types.UnionType, typing.Union):
        hint = next((member for member in get_args(hint) if get_origin(member) is Literal), hint)
    if get_origin(hint) is not Literal:
        msg = f"{recipe.__name__} has no {AVAILABILITY_PARAMETER!r} parameter annotated with a Literal."
        raise TypeError(msg)
    return tuple(str(value) for value in get_args(hint))


def check_availability_table(recipe: Any, source: AvailabilitySource | None = None) -> None:  # noqa: ANN401
    """Check an availability table against the recipe it belongs to.

    Every key must be a value of the recipe's ``satellite`` Literal, every interval must end on or
    after its start, and the intervals of a satellite must be sorted and must not overlap.

    Args:
        recipe (Any): The recipe function.
        source (AvailabilitySource | None): The table to check. Defaults to the one the recipe's
            module declares.

    Raises:
        ValueError: If the recipe declares no table, or the table breaks a rule above. The message
            lists all violations.
        TypeError: If the recipe has no ``satellite`` Literal, or the table is malformed (see
            :func:`load_availability_table`).
    """
    if source is None:
        source = get_availability_source(recipe)
        if source is None:
            msg = f"{recipe.__name__} declares no {AVAILABILITY_ATTRIBUTE}."
            raise ValueError(msg)

    table = load_availability_table(source)
    choices = _satellite_choices(recipe)

    problems: list[str] = []
    for satellite, intervals in table.items():
        if satellite not in choices:
            problems.append(f"{satellite!r}: not a value of the satellite parameter of {recipe.__name__}")
        for start, end in intervals:
            if end < start:
                problems.append(f"{satellite!r}: interval {start} to {end} ends before it starts")
        for (_, previous_end), (start, end) in itertools.pairwise(intervals):
            if start <= previous_end:
                problems.append(f"{satellite!r}: interval {start} to {end} is unsorted or overlaps the one before")

    if problems:
        details = "\n  - ".join(problems)
        msg = f"Invalid availability table of {recipe.__name__}:\n  - {details}"
        raise ValueError(msg)


def format_interval(interval: DateInterval) -> str:
    """Render an interval for display, e.g. ``2017-01-01 to 2017-06-30``."""
    start, end = interval
    return start.isoformat() if start == end else f"{start.isoformat()} to {end.isoformat()}"
